import CheckRounded from '@mui/icons-material/CheckRounded';
import CloseRounded from '@mui/icons-material/CloseRounded';
import Chip, { type ChipProps, type ChipTypeMap } from '@mui/material/Chip';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import type { OverridableComponent } from '@mui/material/OverridableComponent';
import { mergeSlotProps } from '@mui/material/utils';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, type ElementType } from 'react';
import { chipStyles } from './sv-chip.styles';

interface SvChipOwnProps {
  /** Controlled selection; adds a check unless icon or avatar is supplied. */
  selected?: boolean | undefined;
}

export type SvChipProps<C extends ElementType = 'div'> = ChipProps<
  C,
  SvChipOwnProps
>;

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvChip: SvChipProps;
  }
  interface Components {
    SvChip?: { defaultProps?: Partial<SvChipProps> | undefined } | undefined;
  }
}

type Slots = NonNullable<SvChipProps['slotProps']>;

export const SvChip = forwardRef<HTMLDivElement, SvChipProps>(
  function SvChip(inProps, ref) {
    const muiDefaults = useDefaultProps<SvChipProps>({
      props: {},
      name: 'MuiChip',
    });
    const svDefaults = useDefaultProps<SvChipProps>({
      props: {},
      name: 'SvChip',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvChip' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiChip' });
    const {
      selected,
      icon,
      avatar,
      deleteIcon = <CloseRounded />,
      className,
      sx: _sx,
      slotProps: _slotProps,
      color = 'default',
      size = 'medium',
      variant = 'filled',
      ...props
    } = resolved;
    const clickable =
      (props.clickable !== false && Boolean(props.onClick)) || props.clickable;
    const rootSx = mergeSx(
      (theme) => chipStyles(theme, { color, size, variant }),
      muiDefaults.sx,
      svDefaults.sx,
      inProps.sx
    );
    const slot = <K extends keyof Slots>(name: K): NonNullable<Slots[K]> =>
      mergeSlotProps(
        inProps.slotProps?.[name],
        mergeSlotProps(
          svDefaults.slotProps?.[name],
          muiDefaults.slotProps?.[name] ?? {}
        )
      ) as NonNullable<Slots[K]>;

    return (
      <Chip
        aria-pressed={
          clickable && selected !== undefined ? selected : undefined
        }
        {...props}
        ref={ref}
        className={clsx(
          'SvChip-root',
          selected && 'SvChip-selected',
          className
        )}
        color={color}
        size={size}
        variant={variant}
        avatar={avatar}
        icon={icon ?? (selected && !avatar ? <CheckRounded /> : undefined)}
        deleteIcon={deleteIcon}
        sx={rootSx}
        slotProps={{
          root: mergeSlotProps(slot('root'), { sx: rootSx }),
          label: mergeSlotProps(slot('label'), {
            sx: { padding: 0, minWidth: 0, '&:empty': { display: 'none' } },
          }),
        }}
      />
    );
  }
) as OverridableComponent<ChipTypeMap<SvChipOwnProps>>;
